from alembic.runtime.migration import MigrationContext

@router.get("/tenants/{tenant_id}/migrations/history")
async def get_tenant_migration_history(
    tenant_id: str,
    engine: Engine = Depends(get_sync_engine),
    current_user: User = Depends(get_current_user)
):
    if tenant_id != current_user.tenant_id and not current_user.is_devops_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to tenant migration status")

    schema_name = f"tenant_{tenant_id}"
    with engine.connect() as conn:
        context = MigrationContext.configure(
            conn,
            opts={"version_table_schema": schema_name}
        )
        current_rev = context.get_current_revision()
    return {"tenant_id": tenant_id, "current_revision": current_rev}
